import java.util.*;

public class DataFrameColumnsMapping {
    private Map<String, Object> columns;

    public DataFrameColumnsMapping() {
        this.columns = new HashMap<>();
    }

    /**
     * Add a column mapping.
     *
     * @param columnName The name of the column to map.
     * @param value       The value associated with the column.
     */
    public void addColumn(String columnName, String value) {
        if (columns.containsKey(columnName)) {
            throw new RuntimeException("Column " + columnName + " already exists in the DataFrame.");
        }
        columns.put(columnName, value);
    }

    /**
     * Check if a column mapping exists for the specified column.
     *
     * @param columnName The name of the column to check.
     * @return True if the column has a mapping, false otherwise.
     */
    public boolean hasColumn(String columnName) {
        return columns.containsKey(columnName);
    }

    /**
     * Remove a column mapping for the specified column.
     *
     * @param columnName The name of the column to remove the mapping for.
     */
    public void removeColumn(String columnName) {
        if (!columns.containsKey(columnName)) {
            throw new RuntimeException("No column mappings found in the DataFrame.");
        }
        columns.remove(columnName);
    }

    /**
     * Print all column mappings.
     */
    public void printMappings() {
        System.out.println("Column Mappings:");
        for (Map.Entry<String, Object> entry : columns.entrySet()) {
            if (entry.getValue() instanceof Map) {
                Map<String, Object> map = (Map<String, Object>) entry.getValue();
                System.out.print(entry.getKey() + ": ");
                printColumns(map);
                System.out.println();
            } else {
                System.out.print(entry.getKey() + " has the value: " + entry.getValue() + "\n");
            }
        }
    }

    /**
     * Helper function to print column mappings recursively.
     *
     * @param map The column mapping to print.
     */
    private void printColumns(Map<String, Object> map) {
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            System.out.print(entry.getKey() + " has the value: ");
            if (entry.getValue() instanceof Map) {
                printColumns((Map<String, Object>) entry.getValue());
            } else {
                System.out.println(entry.getValue());
            }
        }
    }

    public static void main(String[] args) {
        DataFrameColumnsMapping dcf = new DataFrameColumnsMapping();

        // Add some columns
        dcf.addColumn("col1", "value1");
        dcf.addColumn("col2", "value2");

        // Print all column mappings
        dcf.printMappings();
    }
}
